-- Creates a session-local procedure only; no permanent helper or exposed RPC.
set lock_timeout='2s';
create or replace procedure pg_temp.safe_platform_backfill()
language plpgsql as $safe_backfill$
declare changed integer; pending boolean; should_retry boolean; attempts integer; idle_rounds integer;
begin
  idle_rounds:=0; attempts:=0;
  loop
    should_retry:=false;
    begin
      with batch as (
      select c.id,(select t.id from public.tenants t where t.page_id is not null and left(c.post_id,length(t.page_id)+1)=t.page_id||'_' order by t.id limit 1) tenant_id
      from public.comments c where c.tenant_id is null and exists(select 1 from public.tenants t where t.page_id is not null and left(c.post_id,length(t.page_id)+1)=t.page_id||'_')
      order by c.id limit 200 for update of c skip locked
    ) update public.comments c set tenant_id=b.tenant_id from batch b where c.id=b.id and c.tenant_id is null;
      get diagnostics changed=row_count;
      select exists(select 1 from public.comments c where c.tenant_id is null and exists(select 1 from public.tenants t where t.page_id is not null and left(c.post_id,length(t.page_id)+1)=t.page_id||'_')) into pending;
    exception when deadlock_detected or lock_not_available or serialization_failure then
      should_retry:=true;
    end;
    commit;
    if should_retry then
      attempts:=attempts+1;
      if attempts>20 then raise exception 'comments: retry budget exhausted; resume the CALL later';end if;
      perform pg_sleep(least(10.0,0.25*power(2,least(attempts,5))));
    else
      attempts:=0;
      if not pending then exit;end if;
      if changed=0 then idle_rounds:=idle_rounds+1;else idle_rounds:=0;end if;
      if idle_rounds>600 then raise exception 'comments: eligible rows remain locked; resume later';end if;
      perform pg_sleep(0.075);
    end if;
  end loop;
  idle_rounds:=0; attempts:=0;
  loop
    should_retry:=false;
    begin
      with batch as (
      select c.id,(select t.id from public.tenants t where t.page_id=any(c.page_ids) order by t.id limit 1) tenant_id
      from public.comment_rules c where c.tenant_id is null and exists(select 1 from public.tenants t where t.page_id=any(c.page_ids))
      order by c.id limit 200 for update of c skip locked
    ) update public.comment_rules c set tenant_id=b.tenant_id from batch b where c.id=b.id and c.tenant_id is null;
      get diagnostics changed=row_count;
      select exists(select 1 from public.comment_rules c where c.tenant_id is null and exists(select 1 from public.tenants t where t.page_id=any(c.page_ids))) into pending;
    exception when deadlock_detected or lock_not_available or serialization_failure then
      should_retry:=true;
    end;
    commit;
    if should_retry then
      attempts:=attempts+1;
      if attempts>20 then raise exception 'comment_rules: retry budget exhausted; resume the CALL later';end if;
      perform pg_sleep(least(10.0,0.25*power(2,least(attempts,5))));
    else
      attempts:=0;
      if not pending then exit;end if;
      if changed=0 then idle_rounds:=idle_rounds+1;else idle_rounds:=0;end if;
      if idle_rounds>600 then raise exception 'comment_rules: eligible rows remain locked; resume later';end if;
      perform pg_sleep(0.075);
    end if;
  end loop;
